save(i,dict(
 title='The complexity of finding a directed path longer than a shortest path',
 formal='Classify the worst-case complexity of the following decision problem on unrestricted finite directed graphs: given distinct vertices s and t, is there a simple directed s-to-t path with at least dist_G(s,t)+1 edges? The requested distinction is polynomial-time solvability versus NP-completeness. This is the fixed k=1 case of Longest Detour, not the problem with k supplied as part of the input.',
 definitions='The input is a directed graph G=(V,E), with V=[n], n≥2, no loops or parallel arcs, and distinguished s≠t. Both opposite arcs between two vertices are allowed. The graph is unweighted; every arc has length one. A simple s-to-t path is a sequence v₀=s,v₁,…,v_ℓ=t of pairwise distinct vertices with (v_{j−1},v_j)∈E for 1≤j≤ℓ, and its length is ℓ. If t is reachable from s, dist_G(s,t) is the minimum length of such a path. If t is unreachable, the instance is a no-instance. The input lists all vertices and arcs using binary vertex labels; N is the full encoding length. Polynomial time means one deterministic multitape Turing machine that decides every instance in at most C(N+1)^a steps for absolute constants C,a. NP-completeness uses deterministic polynomial-time many-one reductions; in particular, a hardness proof can give a map from Boolean satisfiability instances to these graph instances that preserves yes/no answers. The decision problem is in NP: an at-most-n-vertex path is a polynomial-size certificate, and reachability distance and the path conditions can be checked in polynomial time. No planarity, acyclicity, connectivity or uniqueness of shortest paths is promised.',
 question_type='asymptotic_complexity',answer_criterion='Determine the problem’s complexity in the stated unrestricted directed, unweighted model. A deterministic polynomial-time decision algorithm establishes tractability; a polynomial-time many-one reduction from SAT establishes NP-completeness, since membership in NP is known. The latter excludes a polynomial-time algorithm under P≠NP. The question does not assume a P/NP-complete dichotomy in advance; any different established classification must explain the remaining boundary. Bounds only for planar graphs, or hardness when k is variable, do not classify the fixed k=1 problem.',
 context_blocks=[b('Another shortest path is not enough','The question asks for strictly greater length. A graph may have many different shortest s-to-t paths and still have no simple path longer than them. Finding a second distinct path therefore does not by itself decide the problem.','primary'),b('Repeated vertices change the task','Allowing a walk to revisit a cycle would make it possible to add length without producing the required simple path. The distinct-vertex condition is essential to this complexity question.','primary'),b('A minimal increase can still hide global structure','Shortest paths are efficiently computable, but deciding whether their length can be exceeded by a simple path constrains which vertices can be reused. Here even one additional edge is the unresolved threshold.','journal2023'),b('Planar instances are understood more precisely','The source gives a fixed-parameter algorithm for planar digraphs, and the 2023 follow-up gives an O(n²) algorithm for this k=1 case. These results do not apply to arbitrary digraphs.','planar2023'),b('A nearby NP-completeness result uses a different baseline','Longest Path Above Diameter asks for a path exceeding the graph’s diameter, rather than the distance between prescribed endpoints. Its k=1 hardness theorem does not classify Directed Detour.','journal2023')],
 why='Pinpoints whether even the smallest departure from shortest-path length creates NP-complete difficulty under the simple-path constraint, a basic boundary in directed path algorithms.',references=refs,
 progress=[dict(date='2022',text='The STACS paper gives a planar fixed-parameter algorithm and leaves the general k=1 classification open.',citation='primary'),dict(date='2023',text='The planar follow-up improves the k=1 running time to O(n²). The JCSS version still explicitly retains the general-digraph question.',citation='journal2023')],
 status='source_open',status_note='Read the complete original target and the JCSS 2023 conclusion, and checked the planar follow-up. Exact-target searches through 12 September 2026 found no classification for arbitrary digraphs. A July 2026 second-shortest-simple-path abstract was also inspected, but did not establish a result for the strictly-longer-than-all-shortest-paths predicate here.',model_self_contained=True,requires_context=False,
 importance=dict(score=c['importance']['score'],method='editorial',reason='A canonical minimal detour question exposing the directed boundary between shortest-path computation and simple-path hardness. Existing score retained.',assessed_on=DATE),review_note='Recovered k=1 and the strict length comparison; specified simple paths, graph encoding, unreachable pairs and deterministic complexity conventions. Separated planar algorithms, second distinct paths and the diameter variant.',
 working_summary=dict(sentences=['The input is an unweighted directed graph with specified endpoints.','The problem asks whether any simple path between them is longer than their shortest-path distance.','Only one extra edge is required, and no path may repeat a vertex.','Planar graphs have polynomial algorithms, but the general directed classification remains open in the checked sources.','The NP-completeness of exceeding graph diameter concerns a different problem.'],basis='saved_sources',source_basis='source-text',written_on=DATE,source_refs=['primary','journal2023','planar2023'])
 ),notes=['Restored the k=1 target and strict simple-path length predicate.','Specified graph/encoding, distance, unreachable-input and complexity-classification conventions.','Checked the retained journal question and distinguished planar, second-path and diameter results.'],checked_sources=[r['url'] for r in refs]+['https://papers.ssrn.com/sol3/papers.cfm?abstract_id=7118647'])
